import{_ as r,o,c as a,a4 as n}from"./chunks/framework.BBs01uty.js";const c=JSON.parse('{"title":"金融 SaaS 平台架构叙事：演进与 AI 工程化","description":"","frontmatter":{},"headers":[],"relativePath":"misc/arch-narrative-saas-ai.md","filePath":"misc/arch-narrative-saas-ai.md"}'),e={name:"misc/arch-narrative-saas-ai.md"};function s(l,t,i,g,d,u){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="金融-saas-平台架构叙事-演进与-ai-工程化" tabindex="-1">金融 SaaS 平台架构叙事：演进与 AI 工程化 <a class="header-anchor" href="#金融-saas-平台架构叙事-演进与-ai-工程化" aria-label="Permalink to &quot;金融 SaaS 平台架构叙事：演进与 AI 工程化&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">用途</p><p>面试讲述稿（3~5 分钟版）。主菜是「架构演进 + AI 辅助开发工程化」，适合 AI 全栈方向岗位。按「约束背景 → 结构性决策 → 权衡 → 结果与代价 → 追问准备」组织。<strong>加粗内容为简历事实，其余为讲述话术，请按真实情况核对调整。</strong></p></div><h2 id="一句话故事主线" tabindex="-1">一句话故事主线 <a class="header-anchor" href="#一句话故事主线" aria-label="Permalink to &quot;一句话故事主线&quot;">​</a></h2><blockquote><p>一个金融抵押贷款 SaaS 平台，在既有系统上完成了<strong>双层架构梳理</strong>和<strong>技术栈整体迁移</strong>，并用<strong>模板编辑器打通文档生成全链路</strong>；同时我把架构思维用到了 AI 辅助开发上——用结构化 Prompt + YAML 工作流把 Agent 约束成&quot;设计→规划→实现→测试→评审&quot;的标准化流程，让 AI 协作可复现、可沉淀。</p></blockquote><hr><h2 id="一、约束与背景-为什么做" tabindex="-1">一、约束与背景（为什么做） <a class="header-anchor" href="#一、约束与背景-为什么做" aria-label="Permalink to &quot;一、约束与背景（为什么做）&quot;">​</a></h2><p><strong>项目背景：</strong> 基于金融资产抵押贷款场景的 SaaS 平台，分 <strong>贷前</strong>（抵押物评估、贷款申请审批）和 <strong>贷后</strong>（还款管理、逾期催收、抵押资产管理、风险定级与合规追踪、数据分析报表）两大业务模块。<strong>Forms Gallery</strong> 是贷后独立模块，管理文档模板，支撑信贷资料补充、重新签名、客户正式信件等场景，实现文档生成流程的标准化与自动化。</p><p><strong>当时的困境：</strong></p><ol><li><strong>旧系统结构混乱</strong>：旧版本基于 JS + Vue + Vite + 自研组件库，业务逻辑和 UI 混在一起，新业务（贷后模块）扩展困难</li><li><strong>文档生成是手工活</strong>：信贷资料、正式信件的模板靠开发人员逐一维护静态模板，业务人员改个措辞都要提需求排期</li><li><strong>AI 协作不可控</strong>：用 AI 辅助开发时，Agent 经常&quot;跳步骤&quot;——不测试就宣布完成、方案没评审就动手，结果不可复现</li></ol><p><strong>我的角色：</strong> 高级前端开发工程师，负责核心模块设计与开发、技术架构优化。</p><hr><h2 id="二、结构性决策-讲清楚-为什么" tabindex="-1">二、结构性决策（讲清楚&quot;为什么&quot;） <a class="header-anchor" href="#二、结构性决策-讲清楚-为什么" aria-label="Permalink to &quot;二、结构性决策（讲清楚&quot;为什么&quot;）&quot;">​</a></h2><h3 id="决策-1-双层架构-——-数据构建层与-ui-展示层分离" tabindex="-1">决策 1：双层架构 —— 数据构建层与 UI 展示层分离 <a class="header-anchor" href="#决策-1-双层架构-——-数据构建层与-ui-展示层分离" aria-label="Permalink to &quot;决策 1：双层架构 —— 数据构建层与 UI 展示层分离&quot;">​</a></h3><p><strong>核心决策：</strong> 前端拆成 <strong>数据构建层 + UI 展示层</strong> 两层。</p><ul><li><strong>数据构建层</strong>：负责业务数据的组装——表单 schema、文档模板的数据结构、状态管理，不关心长什么样</li><li><strong>UI 展示层</strong>：负责渲染与交互，从数据层取数，不关心数据从哪来</li></ul><p><strong>为什么这么切（权衡）：</strong></p><ul><li>金融业务表单多、规则复杂，数据结构和展示经常要各自演进（后端接口变了只改数据层，视觉改版只动展示层）</li><li><strong>Forms Gallery 与模板编辑器深度集成</strong>：模板从编辑、预览到生产环境渲染<strong>全链路打通</strong>——编辑器的产出（模板结构）就是生产环境的输入，双层架构让&quot;编辑器数据&quot;和&quot;渲染展示&quot;天然解耦，这是全链路能成立的前提</li></ul><p><strong>这个决策的含义</strong>：把&quot;数据&quot;当资产，把&quot;UI&quot;当消耗品——数据层可以喂给任何展示端（编辑态、预览态、生产渲染），这是架构里&quot;契约先于实现&quot;的典型。</p><h3 id="决策-2-技术栈整体迁移-——-js-vue-→-ts-react" tabindex="-1">决策 2：技术栈整体迁移 —— JS + Vue → TS + React <a class="header-anchor" href="#决策-2-技术栈整体迁移-——-js-vue-→-ts-react" aria-label="Permalink to &quot;决策 2：技术栈整体迁移 —— JS + Vue → TS + React&quot;">​</a></h3><p><strong>决策与权衡：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>旧（JS + Vue + Vite）</th><th>新（TS + React + Vite + Zustand + 自研组件库）</th></tr></thead><tbody><tr><td>类型安全</td><td>弱，重构靠人肉</td><td>TS 全量覆盖，重构有编译器兜底</td></tr><tr><td>状态管理</td><td>分散</td><td>Zustand 轻量集中</td></tr><tr><td>组件体系</td><td>旧自研库</td><td>新自研组件库（对齐新设计规范）</td></tr></tbody></table><p><strong>为什么敢迁（架构师语言）：</strong></p><ul><li>迁移是<strong>渐进式</strong>的（简历写&quot;新版本迁移&quot;，意味着新旧并存）——新模块用新栈，老模块按需迁移，不搞&quot;大爆炸&quot;</li><li><strong>双层架构是迁移的底气</strong>：数据层先迁（纯逻辑，风险低），UI 层跟随——把不可逆的大改动拆成可逆的小步骤，这是&quot;让决策可逆&quot;的实践</li><li>用 AI 辅助（Cursor）主导模块重构，显著提升重构效率</li></ul><h3 id="决策-3-ai-辅助开发的工程化框架-——-架构思维用在-agent-上" tabindex="-1">决策 3：AI 辅助开发的工程化框架 —— 架构思维用在 Agent 上 <a class="header-anchor" href="#决策-3-ai-辅助开发的工程化框架-——-架构思维用在-agent-上" aria-label="Permalink to &quot;决策 3：AI 辅助开发的工程化框架 —— 架构思维用在 Agent 上&quot;">​</a></h3><p><strong>这是差异化亮点，面试时要重点展开：</strong></p><p><strong>问题</strong>：AI 协作不可控——Agent 跳步骤、不测试就宣布完成、结果不可复现，和&quot;测试应该能过先声明完成吧&quot;的合理化是一样的病。</p><p><strong>方案（对应你正在做的 harness 工程）：</strong></p><ul><li><strong>结构化 Prompt 约束</strong>：把任务上下文、输出格式、质量要求结构化，减少 Agent 的自由发挥空间</li><li><strong>YAML 工作流约束流程</strong>：设计 → 规划 → 实现 → 测试 → 评审的标准化流程，每阶段有明确的输入输出，Agent 按流程执行</li><li><strong>Skill 封装复用</strong>：把高频动作（知识初始化、技术审计、状态检查点）封装成可复用技能</li><li><strong>经验教训自动沉淀</strong>：每轮任务结束自动记录经验，知识越用越多</li><li><strong>多 Agent 协同编排（Agent Teams）</strong>：多个 Agent 分工协作，用工作流编排串起来</li></ul><p><strong>为什么这是架构决策</strong>：和微前端定边界、定契约是同一套思维——<strong>把不确定性（Agent 的自由发挥）用机制约束住，让产出可复现、可校验</strong>。你后来做的 hook 门禁（验证证据链、阶段产出校验）就是这个框架的深化。</p><hr><h2 id="三、演进与验证-结果与代价" tabindex="-1">三、演进与验证（结果与代价） <a class="header-anchor" href="#三、演进与验证-结果与代价" aria-label="Permalink to &quot;三、演进与验证（结果与代价）&quot;">​</a></h2><p><strong>结果（简历事实）：</strong></p><ul><li><strong>主导 Forms Gallery 模块</strong>需求分析与技术方案设计，从 0 到 1 开发并上线</li><li>Forms Gallery 与自研模板编辑器深度集成，<strong>模板编辑 → 预览 → 生产渲染全链路打通</strong></li><li>通过 AI 协作开发显著提升重构效率与交付质量</li><li>沉淀了 Skill 封装复用与经验教训自动沉淀的机制</li></ul><p><strong>代价与踩过的坑：</strong></p><ul><li><strong>迁移期双栈并存</strong>：新旧技术栈同时在跑，公共组件库要同时兼容两套——靠组件库分层 + 按模块灰度迁移解决</li><li><strong>AI 输出质量波动</strong>：同一条 Prompt 不同模型、不同上下文产出差异大——靠工作流强制阶段校验兜底（这也正是后来做 hook 门禁的动机）</li><li><strong>模板与生产的对齐</strong>：编辑器预览必须等于生产渲染，否则业务人员&quot;所见非所得&quot;——靠统一渲染内核解决（编辑器和生产共用同一套渲染）</li></ul><p><strong>如果重来会改什么</strong>：会把 <strong>AI 工作流框架的&quot;测试门禁&quot;更早做成硬校验</strong>——早期靠 Prompt 提醒，Agent 还是会跳，后来发现只有机制（工具 + hook）才能真正拦住。</p><hr><h2 id="四、面试追问准备" tabindex="-1">四、面试追问准备 <a class="header-anchor" href="#四、面试追问准备" aria-label="Permalink to &quot;四、面试追问准备&quot;">​</a></h2><table tabindex="0"><thead><tr><th>追问</th><th>回答要点</th></tr></thead><tbody><tr><td>迁移期间新旧并存，公共组件库怎么处理？</td><td>分层：基础组件（框架无关）优先统一，业务组件按模块灰度；新代码强制新栈，旧代码按需迁移</td></tr><tr><td>为什么选 Zustand 而不是 Redux？</td><td>迁移期要轻量渐进，Zustand 心智负担低、TS 支持好；Redux 的规范在双栈并存期是负担</td></tr><tr><td>数据构建层和 UI 展示层会不会过度设计？</td><td>边界来自真实痛点：表单 schema 和视觉改版频率完全不一致，分离后两边独立演进；如果业务简单就不需要</td></tr><tr><td>模板编辑器为什么能和 Forms Gallery 打通？</td><td>统一渲染内核：编辑器预览和生产渲染共用同一套渲染逻辑，编辑产出即生产输入</td></tr><tr><td>结构化 Prompt 和普通 Prompt 有什么区别？</td><td>结构化约束了角色、上下文、输出格式、质量标准，普通 Prompt 靠模型自觉</td></tr><tr><td>YAML 工作流怎么保证 Agent 不跳步骤？</td><td>每阶段有输入输出契约 + 阶段校验；后来升级为工具 + hook 门禁（验证证据链）——软约束变硬约束</td></tr><tr><td>AI 辅助开发最大的坑是什么？</td><td>假完成（说测试过了其实没跑）；对策是证据链：测试报告必须附真实执行记录</td></tr><tr><td>你怎么看&quot;AI 会取代架构师&quot;？</td><td>AI 擅长在约束内生成方案，但&quot;定义约束&quot;（边界、权衡、取舍）是人的活——架构决策的难点从来不是找答案，而是定问题</td></tr></tbody></table><hr><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><a href="/knowledge/engineering/architect.html">什么是架构师</a> - 本叙事稿的框架依据</li><li><a href="/knowledge/template-editor/">自研模板编辑器</a> - 编辑器架构细节</li><li><a href="/knowledge/ai-agent/harness-engineering/function-calling-upgrade.html">Function Calling 引入计划</a> - AI 工作流硬校验的演进方向</li></ul>',42)])])}const p=r(e,[["render",s]]);export{c as __pageData,p as default};
